      'Кения вознаграждает путешественников, которые едут тихо и приватно, — и этот маршрут целиком построен вокруг этой идеи. Девять дней, три ландшафта и ничего общего с кем-либо за пределами вашей собственной группы: лагеря в эксклюзивное пользование, разбитые в тени Килиманджаро в Амбосели, культурно насыщенное пребывание в сухой северной стране Самбуру и приватный уголок Масаи-Мара, до которого большинство посетителей никогда не добирается.',
      'Это не сафари-чеклист. Это три намеренно разные Кении, каждой из которых отведено достаточно времени, чтобы по-настоящему в неё погрузиться: большие бивненосцы и фоны Килиманджаро в Амбосели, поющие колодцы и живая культура самбуру на севере и плотность дикой природы в малопосещаемом юго-западном углу Мары. Одна и та же доверенная команда гидов путешествует с вами на всём протяжении, так что опыт — и доверие — накапливаются в течение всей поездки, а не начинаются заново на каждой остановке.',
      'Как рождённый в Танзании, базирующийся в Аруше оператор, теперь развивающий свой кенийский маршрут, мы проектируем этот маршрут так же, как проектируем наши восточноафриканские маршруты: индивидуально под ваши даты, приватно на всём протяжении и под руководством профессиональных, сертифицированных гидов, знающих местность.',
